INSERT INTO series (user_id, series_group_id, name)
SELECT e.user_id, e.series_group_id, #{defaultName}
FROM series_group e
JOIN template_series_group g ON g.name = e.name AND g.template_id = #{templateId}
WHERE e.user_id = #{userId}
  AND NOT EXISTS (
      SELECT 1 FROM series c
      WHERE c.user_id = e.user_id AND c.series_group_id = e.series_group_id AND c.name = #{defaultName}
  )
